attention 가중치를 꺼내 볼 수 있도록 nn.MultiheadAttention을 직접 사용한다.

class Block(nn.Module):
    def __init__(self, d, heads):
        super().__init__()
        self.ln1, self.ln2 = nn.LayerNorm(d), nn.LayerNorm(d)
        self.attn = nn.MultiheadAttention(d, heads, batch_first=True)
        self.ff = nn.Sequential(nn.Linear(d, 4 * d), nn.GELU(), nn.Linear(4 * d, d))
        self.last_attn = None

    def forward(self, x):
        h = self.ln1(x)
        a, w = self.attn(h, h, h, need_weights=True, average_attn_weights=False)
        self.last_attn = w.detach()          # (batch, heads, L, L)
        x = x + a
        return x + self.ff(self.ln2(x))


class TinyMLM(nn.Module):
    def __init__(self, d=64, heads=4, layers=2):
        super().__init__()
        self.tok = nn.Embedding(V + 1, d)    # 잔기 20 + 마스크 1
        self.pos = nn.Embedding(L, d)        # 학습되는 위치 임베딩 (고정 길이)
        self.blocks = nn.ModuleList([Block(d, heads) for _ in range(layers)])
        self.ln = nn.LayerNorm(d)
        self.out = nn.Linear(d, V)

    def forward(self, x):
        h = self.tok(x) + self.pos(torch.arange(x.size(1), device=x.device))
        for b in self.blocks:
            h = b(h)
        return self.out(self.ln(h))


model = TinyMLM().to(DEVICE)
print("parameters:", sum(p.numel() for p in model.parameters()))

RCSB PDB에서 3개를 받는다 (출처: 

files​.rcsb​.org​/download/.pdb). 표준 잔기 중 Cα가 있는 것만 쓰고, 서열은 같은 잔기들로 만든다.
잔기 번호에 **빈 구간(결측 잔기)**이 있으면 서열이 이어 붙여지므로 경고를 출력한다.

PROTEINS = {"1UBQ": "A", "1PGA": "A", "1AKI": "A"}
for pid in PROTEINS:
    path = PDB_DIR / f"{pid}.pdb"
    if not path.exists():
        print("downloading", pid)
        urllib.request.urlretrieve(f"https://files.rcsb.org/download/{pid}.pdb", path)


def load_structure(pid, chain_id):
    s = PDBParser(QUIET=True).get_structure(pid, PDB_DIR / f"{pid}.pdb")
    residues = [r for r in s[0][chain_id] if r.id[0] == " " and "CA" in r]
    seq = "".join(seq1(r.get_resname()) for r in residues)
    nums = [r.id[1] for r in residues]
    if any(b - a != 1 for a, b in zip(nums, nums[1:])):
        print(f"[경고] {pid}: 잔기 번호에 빈 구간이 있음 — 서열이 이어 붙여짐")
    def cb_coord(r):
        if r.get_resname() == "GLY":
            return r["CA"].coord                                    # 글리신만 Cα를 쓴다
        if "CB" in r:
            return r["CB"].coord
        print(f"[경고] {pid} {r.get_resname()}{r.id[1]}: Cβ 원자가 없어 Cα로 대체 (접촉 정답이 달라질 수 있음)")
        return r["CA"].coord

    cb = np.array([cb_coord(r) for r in residues])
    dist = np.linalg.norm(cb[:, None] - cb[None], axis=-1)
    return seq, dist


structs = {pid: load_structure(pid, ch) for pid, ch in PROTEINS.items()}
MIN_SEP = 12         # 서열 거리 ≥ 12인 쌍(중·장거리)만 평가. 작은 단백질이라 24 대신 12를 쓴다
CUTOFF = 8.0
for pid, (seq, dist) in structs.items():
    L = len(seq)
    iu = np.triu_indices(L, k=MIN_SEP)
    print(f"{pid}: L={L}  접촉 쌍(<{CUTOFF:.0f}Å, 거리≥{MIN_SEP}): {(dist[iu] < CUTOFF).sum():4d} / {len(iu[0])}  → 밀도 {(dist[iu] < CUTOFF).mean():.3f}")

def precision_top(scores, dist, k=None, min_sep=MIN_SEP):
    L = scores.shape[0]
    k = k or max(1, L // 5)
    iu = np.triu_indices(L, k=min_sep)
    top = np.argsort(-scores[iu])[:k]
    return float((dist[iu][top] < CUTOFF).mean())


def sep_prior(L):
    i, j = np.indices((L, L))
    return -np.abs(i - j).astype(float)                      # 서열상 가까운 쌍일수록 높은 점수


for pid, (seq, dist) in structs.items():
    L = len(seq)
    iu = np.triu_indices(L, k=MIN_SEP)
    print(f"{pid}: random 기대 {(dist[iu] < CUTOFF).mean():.2f} | 서열 거리 prior {precision_top(sep_prior(L), dist):.2f}")

