RCSB에서 1UBQ, 1PGA 구조를 내려받아 예측 구조와 CA 원자로 겹쳐 RMSD를 잰다. 서열 길이가 같고 잔기 순서가 같다는 가정(두 구조 모두 해당)이다.

def ca_atoms(structure):
    return [r["CA"] for r in structure[0]["A"] if r.id[0] == " " and "CA" in r]


def rmsd_to_experiment(pid, pred_pdb):
    path = f"{pid}.pdb"
    for attempt in range(3):                                      # RCSB 연결이 일시적으로 끊길 수 있다 (Colab 실행에서 한 번 겪었다)
        try:
            urllib.request.urlretrieve(f"https://files.rcsb.org/download/{pid}.pdb", path)
            break
        except OSError:
            if attempt == 2:
                raise
            time.sleep(3)
    exp = PDBParser(QUIET=True).get_structure("exp", path)
    pred = PDBParser(QUIET=True).get_structure("pred", io.StringIO(pred_pdb))
    pred_ca = [r["CA"] for r in pred[0].get_residues() if "CA" in r]
    exp_ca = ca_atoms(exp)
    assert len(exp_ca) == len(pred_ca), (len(exp_ca), len(pred_ca))
    sup = Superimposer()
    sup.set_atoms(exp_ca, pred_ca)
    return sup.rms


for name, pid in [("ubiquitin (1UBQ)", "1UBQ"), ("protein G B1 (1PGA)", "1PGA")]:
    print(f"{name:22s} CA RMSD vs experiment: {rmsd_to_experiment(pid, folded[name][0]):.2f} Å")

서열마다 평균 임베딩(<cls>·패딩 제외)을 여러 층에서 뽑는다. hidden_states[0]은 임베딩 층 출력, hidden_states[24]는 마지막 층이다.
중간 층이 마지막 층보다 나은지는 과제마다 다르다†.

LAYERS = [6, 12, 18, 24]
SPECIAL = torch.tensor(tok.all_special_ids, device=DEVICE)


@torch.no_grad()
def embed(seqs, layers=LAYERS, batch=64):
    out = {l: [] for l in layers}
    for s in range(0, len(seqs), batch):
        enc = tok(list(seqs[s:s + batch]), return_tensors="pt", padding=True).to(DEVICE)
        hs = model(**enc, output_hidden_states=True).hidden_states
        m = (enc["attention_mask"].bool() & ~torch.isin(enc["input_ids"], SPECIAL)).float()     # 패딩·<cls> 제외
        for l in layers:
            out[l].append(((hs[l] * m.unsqueeze(-1)).sum(1) / m.sum(1, keepdim=True)).float().cpu())
    return {l: torch.cat(v).numpy() for l, v in out.items()}


# 정합성: 단독 입력과 패딩된 배치 입력의 평균 임베딩이 같아야 한다
a = embed([s])[24]
b = embed([s, s[:250]])[24]
print("패딩 유무에 따른 마지막 층 평균 임베딩 최대 차이:", float(np.abs(a[0] - b[0]).max()))

두 방법의 개별 신뢰구간이 겹친다는 사실만으로 차이의 유무를 판단할 수 없다. 같은 test 서열에서 AUROC 차이를 직접 재표본한다 (인접 창의 상관을 무시하므로 여전히 낙관적일 수 있다).

def paired_delta(t, f_a, f_b, n_boot=1000, seed=0):
    pa, pb = fitted[(t, f_a)]["p"], fitted[(t, f_b)]["p"]
    yt = data[t]["te"].label.values
    rs, ds = np.random.RandomState(seed), []
    for _ in range(n_boot):
        i = rs.randint(0, len(yt), len(yt))
        if yt[i].min() != yt[i].max():
            ds.append(roc_auc_score(yt[i], pa[i]) - roc_auc_score(yt[i], pb[i]))
    return roc_auc_score(yt, pa) - roc_auc_score(yt, pb), *np.percentile(ds, [2.5, 97.5])


for t in data:
    best = max((f for f in data[t]["feats"] if f.startswith("NT")), key=lambda f: fitted[(t, f)]["cv_auroc"])
    d_, lo_, hi_ = paired_delta(t, best, "6-mer freq")
    print(f"{t:17s} {best} − 6-mer: ΔAUROC = {d_:+.3f} [{lo_:+.3f}, {hi_:+.3f}]  (층은 train CV로만 선택)")

Geneformer 저장소는 토큰 사전, 유전자별 코퍼스 중앙값, Ensembl 매핑을 pickle로 배포한다. pickle은 불러오는 순간 임의 코드를 실행시킬 수 있다. 신뢰할 수 있는 저장소라도 (1) 어떤 전역 객체를 끌어오는지 불러오기 전에 보고, (2) 필요한 클래스만 허용하는 Unpickler로 읽는다.

아래 opcode 검사는 사람이 읽기 위한 점검용이다(STACK_GLOBAL 직전 문자열 두 개를 보는 근사라 모든 경우를 잡는다고 보장하지 않는다). 실제 방어는 find_class 허용 목록이다.

REV = "1f7fbae4e469a5f4f1af8c111a529cfe1b3829f5"      # 이 노트북에서 쓴 저장소 커밋 (재현용 고정)
REPO = "ctheodoris/Geneformer"
FILES = {
    "v1": dict(model="Geneformer-V1-10M", tok="geneformer/gene_dictionaries_30m/token_dictionary_gc30M.pkl",
               med="geneformer/gene_dictionaries_30m/gene_median_dictionary_gc30M.pkl",
               map="geneformer/gene_dictionaries_30m/ensembl_mapping_dict_gc30M.pkl", max_len=2048, special=False),
    "v2": dict(model="Geneformer-V2-104M", tok="geneformer/token_dictionary_gc104M.pkl",
               med="geneformer/gene_median_dictionary_gc104M.pkl",
               map="geneformer/ensembl_mapping_dict_gc104M.pkl", max_len=4096, special=True),
}


def fetch(rel):
    return hf_hub_download(REPO, rel, revision=REV)


def audit_pickle_globals(path):
    # 근사 점검: STACK_GLOBAL 직전 문자열 두 개를 보므로 MEMOIZE/BINGET으로 참조된 문자열, INST/OBJ/NEWOBJ_EX 등은 추적하지 못한다. 따라서 보조 출력일 뿐 방어 수단이 아니다
    data = Path(path).read_bytes()
    seen, strs = set(), []
    for op, arg, _ in pickletools.genops(data):
        if op.name in ("SHORT_BINUNICODE", "BINUNICODE", "UNICODE"):
            strs.append(arg)
        elif op.name == "GLOBAL":
            seen.add(arg)
        elif op.name == "STACK_GLOBAL":
            seen.add(" ".join(strs[-2:]))
    return sorted(seen)


class SafeUnpickler(pickle.Unpickler):
    ALLOWED = {("numpy", "dtype"), ("numpy.core.multiarray", "scalar"), ("numpy._core.multiarray", "scalar")}

    def find_class(self, module, name):
        if (module, name) in self.ALLOWED:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(f"blocked global: {module}.{name}")


def load_pkl(path):
    with open(path, "rb") as f:
        return SafeUnpickler(f).load()


for v, cfg in FILES.items():
    for kind in ["tok", "med", "map"]:
        p = fetch(cfg[kind])
        print(f"{v} {kind:3s} {Path(cfg[kind]).name:42s} 참조하는 전역 객체: {audit_pickle_globals(p) or '없음(내장 자료형뿐)'}")

# 허용 목록이 실제로 막는지: 무해한 print를 실행하려는 가짜 pickle
class Evil:
    def __reduce__(self):
        return (print, ("!!! 코드가 실행되었다 !!!",))


evil = pickle.dumps(Evil())
try:
    SafeUnpickler(io.BytesIO(evil)).load()
